// Flashcards (fixed, spaced repetition) and quizzes (fresh every time), generated by Gemini from the lecture slides
import { h, icon, esc, toast } from './ui.js';

const DAY = 86400000;
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
let ctx = null; // { api, lib, pdfjsLib, node(id), saveLib(), openLecture(id, page) }
export function initStudy(c) { ctx = c; }

// ---------------- Gemini ----------------
let modelsP = null, goodModel = null;
function key() { return (ctx.lib.settings.geminiKey || '').trim(); }
const ver = n => (n.match(/gemini-(\d+(?:\.\d+)?)/) || [0, 0])[1] * 1;
// candidate models, best first: newest stable flash, newest flash-lite, latest aliases, then older flashes
async function models() {
  return modelsP ||= (async () => {
    try {
      const r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?pageSize=200&key=${encodeURIComponent(key())}`);
      const j = await r.json();
      if (j.error) throw new Error(j.error.message);
      const names = (j.models || []).filter(m => (m.supportedGenerationMethods || []).includes('generateContent')).map(m => m.name.replace('models/', ''));
      const byVer = (a, b) => ver(b) - ver(a);
      const stable = names.filter(n => /^gemini-\d+(\.\d+)?-flash$/.test(n)).sort(byVer);
      const lite = names.filter(n => /^gemini-\d+(\.\d+)?-flash-lite$/.test(n)).sort(byVer);
      const alias = ['gemini-flash-latest', 'gemini-flash-lite-latest'].filter(n => names.includes(n));
      const other = names.filter(n => /flash/.test(n) && !/image|tts|live|audio|embedding/.test(n)).sort(byVer);
      return [...new Set([...stable.slice(0, 2), ...alias, ...lite.slice(0, 2), ...other])].slice(0, 8);
    } catch (e) { modelsP = null; throw e; }
  })();
}
async function callModel(model, body) {
  const r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(key())}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  const j = await r.json().catch(() => ({}));
  return { status: r.status, j };
}
async function gemini(prompt, schema, onStatus) {
  if (!key()) throw Object.assign(new Error('nokey'), { code: 'nokey' });
  const list = await models();
  const order = goodModel ? [goodModel, ...list.filter(m => m !== goodModel)] : list;
  const body = { contents: [{ role: 'user', parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', responseSchema: schema, temperature: 0.9 } };
  let last = '';
  for (const model of order) {
    for (let attempt = 0; attempt < 2; attempt++) {
      onStatus && onStatus(model);
      const { status, j } = await callModel(model, body);
      if (!j.error && status < 300) {
        const txt = j.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') || '';
        try { const out = JSON.parse(txt); goodModel = model; return out; } catch { last = 'رد غير مفهوم من Gemini'; break; }
      }
      last = `${model}: ${j.error?.message || 'HTTP ' + status}`;
      const quotaZero = /limit: 0|quota/i.test(j.error?.message || '') && !/retry in [0-9]/i.test(j.error?.message || '');
      if (status === 503 && attempt === 0) { await new Promise(r => setTimeout(r, 2500)); continue; }
      if (status === 429 && !quotaZero && attempt === 0) { await new Promise(r => setTimeout(r, 3000)); continue; }
      if (status === 400 && /API key/i.test(j.error?.message || '')) throw new Error(j.error.message);
      break; // try next model
    }
  }
  throw new Error(last || 'Gemini ما رد');
}

// ---------------- lecture text ----------------
const textCache = new Map();
async function lectureText(id) {
  if (textCache.has(id)) return textCache.get(id);
  const bytes = await ctx.api.readPdf(id);
  if (!bytes) throw new Error('ملف المحاضرة مو موجود على الجهاز');
  const doc = await ctx.pdfjsLib.getDocument({ data: bytes }).promise;
  const notes = (await ctx.api.loadLecture(id)).pages || {};
  const strip = s => String(s || '').replace(/<[^>]+>/g, ' ');
  let out = '';
  for (let i = 1; i <= doc.numPages; i++) {
    const tc = await (await doc.getPage(i)).getTextContent();
    const t = tc.items.map(x => x.str).join(' ').replace(/\s+/g, ' ').trim();
    const pg = notes[i - 1] || {};
    const mine = [pg.note, ...(pg.items || []).filter(x => x.t === 'text').map(x => strip(x.html))].filter(Boolean).join(' | ');
    out += `\n[Slide ${i}] ${t}${mine ? `\n[Student notes on slide ${i}] ${mine}` : ''}`;
  }
  await doc.destroy();
  const res = { text: out.slice(0, 120000), pages: doc.numPages };
  textCache.set(id, res);
  return res;
}

// ---------------- cards storage ----------------
async function loadCards(id) { const d = await ctx.api.loadFile('cards/' + id + '.json'); return d?.cards || []; }
async function saveCards(id, cards) { await ctx.api.saveFile('cards/' + id + '.json', { cards }); }
export async function cardCount(id) { const c = await loadCards(id); return { total: c.length, due: c.filter(x => (x.due || 0) <= Date.now()).length }; }

const CARD_SCHEMA = { type: 'OBJECT', properties: { cards: { type: 'ARRAY', items: { type: 'OBJECT', properties: { q: { type: 'STRING' }, a: { type: 'STRING' }, page: { type: 'INTEGER' } }, required: ['q', 'a', 'page'] } } }, required: ['cards'] };
async function generateCards(id, n, existing, onStatus) {
  const { text } = await lectureText(id);
  const name = ctx.node(id)?.name || '';
  const avoid = existing.length ? `\nThese cards ALREADY exist — do NOT repeat or rephrase them, cover different facts:\n${existing.map(c => '- ' + c.q).join('\n')}` : '';
  const prompt = `You are making spaced-repetition flashcards for a medical student from the lecture "${name}".
Write exactly ${n} high-yield flashcards based ONLY on the slides below (and the student's own notes if present).
Rules: one fact per card; question short and specific; answer concise (max ~25 words); keep medical terms in English exactly as on the slides; prefer facts likely to appear in exams (relations, boundaries, nerve/blood supply, contents, clinical notes); "page" = the slide number the fact comes from.${avoid}

LECTURE:
${text}`;
  const r = await gemini(prompt, CARD_SCHEMA, onStatus);
  return (r.cards || []).slice(0, n).map(c => ({ id: uid(), q: String(c.q).trim(), a: String(c.a).trim(), page: Math.max(1, Number(c.page) || 1), created: Date.now(), due: 0, interval: 0, ease: 2.5, reps: 0, lapses: 0 }));
}

// spaced repetition (SM-2 style)
function schedule(c, g) {
  c.ease ||= 2.5; c.interval ||= 0; c.reps ||= 0;
  if (g === 0) { c.lapses = (c.lapses || 0) + 1; c.reps = 0; c.interval = 0; c.ease = Math.max(1.3, c.ease - 0.2); c.due = Date.now() + 10 * 60000; return; }
  if (g === 1) { c.interval = Math.max(1, Math.round((c.interval || 1) * 1.2)); c.ease = Math.max(1.3, c.ease - 0.15); }
  if (g === 2) c.interval = c.reps === 0 ? 1 : c.reps === 1 ? 3 : Math.round(c.interval * c.ease);
  if (g === 3) { c.interval = c.reps === 0 ? 3 : Math.round(Math.max(1, c.interval) * c.ease * 1.3); c.ease += 0.15; }
  c.reps++; c.due = Date.now() + c.interval * DAY;
}
function preview(c, g) {
  const t = { ...c }; schedule(t, g);
  if (g === 0) return '١٠ د';
  return t.interval === 1 ? 'بكرة' : `${t.interval} يوم`;
}

// ---------------- overlay shell ----------------
function overlay(title, sub) {
  const close = h('button', { class: 'icon-btn', type: 'button', 'aria-label': 'إغلاق', html: '<svg class="i" viewBox="0 0 24 24"><path d="M18 6 6 18M6 6l12 12"/></svg>' });
  const body = h('div', { class: 'st-body' });
  const head = h('div', { class: 'st-head' }, h('div', { style: { flex: 1 } }, h('div', { class: 'st-title' }, title), h('div', { class: 'st-sub' }, sub || '')), close);
  const box = h('div', { class: 'st-box', role: 'dialog', 'aria-modal': 'true' }, head, body);
  const bg = h('div', { class: 'st-bg' }, box);
  const done = () => { bg.remove(); document.removeEventListener('keydown', onKey, true); };
  const onKey = e => { if (e.key === 'Escape' && !document.querySelector('.modal-bg')) { e.stopPropagation(); done(); } else if (bg._key) bg._key(e); };
  close.onclick = done;
  document.addEventListener('keydown', onKey, true);
  document.getElementById('layer').append(bg);
  return { body, done, bg, setSub: t => { head.querySelector('.st-sub').textContent = t; } };
}
function busy(body, text) { body.innerHTML = ''; body.append(h('div', { class: 'st-busy' }, h('div', { class: 'spin' }), h('div', {}, text))); }
function errBox(body, e, retry) {
  body.innerHTML = '';
  const nokey = e.code === 'nokey' || /API key/i.test(e.message);
  body.append(h('div', { class: 'st-empty' },
    h('div', { style: { fontWeight: 700, fontSize: '16px' } }, nokey ? 'يحتاج مفتاح Gemini' : 'صار خطأ'),
    h('div', { class: 'ltr', style: { color: 'var(--muted)', maxWidth: '520px' } }, nokey ? 'ضيف المفتاح من الإعدادات ← الذكاء الاصطناعي.' : e.message),
    retry ? h('button', { class: 'btn primary', type: 'button', onclick: retry }, 'حاول مرة ثانية') : null));
}
const countPicker = (label, opts, def, onPick) => {
  const row = h('div', { class: 'chips', style: { justifyContent: 'center' } });
  for (const n of opts) row.append(h('button', { type: 'button', class: 'chip' + (n === def ? ' on' : ''), style: n === def ? { borderColor: 'var(--accent)', color: 'var(--text)' } : {}, onclick: () => onPick(n) }, label(n)));
  return row;
};

// ---------------- flashcards ----------------
// ids: one lecture or several (a tag)
export async function openCards(ids, title) {
  const ov = overlay(title, '');
  const multi = ids.length > 1;
  let all = []; // {lid, card}
  async function reload() { all = []; for (const id of ids) for (const c of await loadCards(id)) all.push({ lid: id, c }); }
  async function persist(lid) { await saveCards(lid, all.filter(x => x.lid === lid).map(x => x.c)); }
  async function gen(n, onlyMissing) {
    for (const [k, id] of ids.entries()) {
      const mine = all.filter(x => x.lid === id).map(x => x.c);
      if (onlyMissing && mine.length) continue;
      busy(ov.body, multi ? `أجهز بطاقات "${ctx.node(id)?.name}" (${k + 1}/${ids.length})…` : `أجهز ${n} بطاقة من المحاضرة…`);
      const fresh = await generateCards(id, n, mine, m => { const el = ov.body.querySelector('.st-busy div:last-child'); if (el && !el.dataset.base) el.dataset.base = el.textContent; if (el) el.textContent = el.dataset.base + ' (' + m + ')'; });
      for (const c of fresh) all.push({ lid: id, c });
      await persist(id);
    }
  }
  async function home() {
    await reload();
    const body = ov.body; body.innerHTML = '';
    const due = all.filter(x => (x.c.due || 0) <= Date.now());
    ov.setSub(all.length ? `${all.length} بطاقة · ${due.length} مستحقة الحين` : '');
    const missing = ids.filter(id => !all.some(x => x.lid === id));
    if (!all.length || (multi && missing.length)) {
      const def = 20;
      body.append(h('div', { class: 'st-empty' },
        h('div', { html: icon('cards', 40), style: { color: 'var(--accent)' } }),
        h('div', { style: { fontWeight: 700, fontSize: '17px' } }, multi ? `${missing.length} من المحاضرات ما لها بطاقات للحين` : 'ما فيه بطاقات للمحاضرة هذي للحين'),
        h('div', { style: { color: 'var(--muted)' } }, 'تنسوى مرة وحدة وتبقى محفوظة، وتراجعها بالمراجعة المتباعدة. كم بطاقة نبدأ فيها؟'),
        countPicker(n => n + ' بطاقة', [10, 20, 30], def, n => run(() => gen(n, true)))));
      if (!all.length) return;
    }
    const acts = h('div', { class: 'st-acts' },
      h('button', { class: 'btn primary', type: 'button', disabled: !due.length, html: icon('cards', 16) + (due.length ? `ابدأ المراجعة (${due.length})` : 'ما فيه بطاقات مستحقة الحين'), onclick: () => review(due) }),
      h('button', { class: 'btn', type: 'button', onclick: () => review(shuffle([...all])) }, 'راجع الكل'),
      multi ? null : h('button', { class: 'btn ghost', type: 'button', html: icon('plus', 16) + 'إضافة المزيد', onclick: e => moreMenu(e.currentTarget) }));
    body.append(acts);
    const list = h('div', { class: 'st-list' });
    all.sort((a, b) => (a.c.page || 0) - (b.c.page || 0)).forEach(({ lid, c }) => {
      const st = c.reps ? (c.due <= Date.now() ? 'مستحقة' : 'بعد ' + Math.max(1, Math.ceil((c.due - Date.now()) / DAY)) + ' يوم') : 'جديدة';
      list.append(h('div', { class: 'st-card' },
        h('div', { class: 'q ltr', dir: 'auto' }, c.q), h('div', { class: 'a ltr', dir: 'auto' }, c.a),
        h('div', { class: 'm' }, h('span', {}, st), h('button', { class: 'linkbtn', type: 'button', onclick: () => { ov.done(); ctx.openLecture(lid, c.page - 1); } }, (multi ? ctx.node(lid)?.name + ' · ' : '') + 'سلايد ' + c.page),
          h('button', { class: 'linkbtn', type: 'button', style: { color: 'var(--danger)' }, onclick: async () => { all = all.filter(x => x.c !== c); await persist(lid); home(); } }, 'حذف'))));
    });
    body.append(list);
  }
  function moreMenu(anchor) {
    const r = anchor.getBoundingClientRect();
    const m = h('div', { class: 'menu', style: { left: r.left + 'px', top: r.bottom + 6 + 'px' } }, h('div', { class: 'mt' }, 'كم بطاقة نزيد؟'));
    for (const n of [5, 10, 15, 20]) m.append(h('button', { class: 'mi', type: 'button', onclick: () => { m.remove(); run(() => gen(n, false)); } }, `+ ${n} بطاقات جديدة`));
    document.getElementById('layer').append(m);
    setTimeout(() => document.addEventListener('pointerdown', function f(e) { if (!m.contains(e.target)) { m.remove(); document.removeEventListener('pointerdown', f, true); } }, true));
  }
  async function run(fn) { try { await fn(); await home(); } catch (e) { errBox(ov.body, e, () => home()); } }
  function review(queue) {
    let i = 0, shown = false, done = 0;
    const body = ov.body;
    const draw = () => {
      body.innerHTML = '';
      if (i >= queue.length) {
        ov.bg._key = null;
        body.append(h('div', { class: 'st-empty' }, h('div', { style: { fontSize: '20px', fontWeight: 700 } }, 'خلصت المراجعة'), h('div', { style: { color: 'var(--muted)' } }, `راجعت ${done} بطاقة. البطاقات اللي نسيتها بترجع لك بعد شوي.`), h('button', { class: 'btn primary', type: 'button', onclick: home }, 'رجوع للبطاقات')));
        return;
      }
      const { lid, c } = queue[i];
      body.append(h('div', { class: 'st-prog' }, h('div', { style: { width: (i / queue.length * 100) + '%' } })),
        h('div', { class: 'st-flip' + (shown ? ' shown' : '') },
          h('div', { class: 'q ltr', dir: 'auto' }, c.q),
          shown ? h('div', { class: 'a ltr', dir: 'auto' }, c.a) : null,
          h('button', { class: 'linkbtn', type: 'button', onclick: () => { ov.done(); ctx.openLecture(lid, c.page - 1); } }, (multi ? ctx.node(lid)?.name + ' · ' : '') + 'سلايد ' + c.page)));
      if (!shown) body.append(h('div', { class: 'st-acts', style: { justifyContent: 'center' } }, h('button', { class: 'btn primary', type: 'button', style: { minWidth: '220px' }, onclick: () => { shown = true; draw(); } }, 'اظهر الجواب (مسافة)')));
      else {
        const g = h('div', { class: 'st-grades' });
        [['نسيت', '#E5484D'], ['صعبة', '#F08A4B'], ['تمام', '#3FBF7F'], ['سهلة', '#5B9BF0']].forEach(([l, col], k) => g.append(h('button', { type: 'button', style: { borderColor: col }, onclick: () => grade(k) }, h('b', {}, l), h('span', {}, preview(c, k) + ` · ${k + 1}`))));
        body.append(g);
      }
      ov.setSub(`${i + 1} / ${queue.length}`);
    };
    const grade = async k => {
      const { lid, c } = queue[i];
      schedule(c, k); done++;
      if (k === 0) queue.push(queue[i]);
      await persist(lid);
      i++; shown = false; draw();
    };
    ov.bg._key = e => {
      if (i >= queue.length) return;
      if (!shown && (e.key === ' ' || e.key === 'Enter')) { e.preventDefault(); shown = true; draw(); }
      else if (shown && ['1', '2', '3', '4'].includes(e.key)) { e.preventDefault(); grade(Number(e.key) - 1); }
    };
    draw();
  }
  try { await home(); } catch (e) { errBox(ov.body, e, () => home()); }
}

// ---------------- quiz ----------------
const QUIZ_SCHEMA = { type: 'OBJECT', properties: { questions: { type: 'ARRAY', items: { type: 'OBJECT', properties: { q: { type: 'STRING' }, options: { type: 'ARRAY', items: { type: 'STRING' } }, correct: { type: 'INTEGER' }, explanation: { type: 'STRING' }, page: { type: 'INTEGER' }, lecture: { type: 'INTEGER' } }, required: ['q', 'options', 'correct', 'explanation', 'page'] } } }, required: ['questions'] };
const shuffle = a => { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
export async function openQuiz(ids, title) {
  const ov = overlay(title, 'اختبار جديد كل مرة');
  const start = () => {
    ov.body.innerHTML = ''; ov.bg._key = null;
    ov.body.append(h('div', { class: 'st-empty' }, h('div', { html: icon('quiz', 40), style: { color: 'var(--accent)' } }), h('div', { style: { fontWeight: 700, fontSize: '17px' } }, 'كم سؤال تبي؟'),
      h('div', { style: { color: 'var(--muted)' } }, 'أسئلة اختيار من متعدد، تتغير كل مرة.'), countPicker(n => n + ' أسئلة', [5, 10, 15, 20], 10, n => make(n))));
  };
  async function make(n) {
    try {
      busy(ov.body, 'أجهز الاختبار…');
      const texts = [];
      for (const [k, id] of ids.entries()) { const t = await lectureText(id); texts.push(`=== LECTURE ${k + 1}: ${ctx.node(id)?.name} ===${t.text.slice(0, Math.floor(110000 / ids.length))}`); }
      const seed = Math.random().toString(36).slice(2, 8);
      const prompt = `Make a ${n}-question multiple-choice exam for a medical student from the lecture material below. Variation seed: ${seed} — pick a DIFFERENT random selection of topics than usual, spread across all slides${ids.length > 1 ? ' and all lectures' : ''}.
Rules: 4 options each, exactly one correct, plausible distractors from the same lecture, exam style (MCQ like medical school finals); keep terms in English as on the slides; "correct" is the 0-based index; "explanation" is one or two short sentences; "page" is the slide number; "lecture" is the lecture number (1-based).

${texts.join('\n\n')}`;
      const r = await gemini(prompt, QUIZ_SCHEMA, m => { const el = ov.body.querySelector('.st-busy div:last-child'); if (el) el.textContent = 'أجهز الاختبار… (' + m + ')'; });
      const qs = (r.questions || []).filter(q => q.options?.length >= 2).slice(0, n).map(q => {
        const order = shuffle(q.options.map((o, i) => i));
        return { ...q, options: order.map(i => q.options[i]), correct: order.indexOf(q.correct), lid: ids[Math.max(0, Math.min(ids.length - 1, (q.lecture || 1) - 1))] };
      });
      if (!qs.length) throw new Error('ما طلع أسئلة، جرّب مرة ثانية');
      play(qs);
    } catch (e) { errBox(ov.body, e, start); }
  }
  function play(qs) {
    let i = 0, score = 0, picked = null; const wrong = [];
    const draw = () => {
      const body = ov.body; body.innerHTML = '';
      if (i >= qs.length) {
        ov.bg._key = null; ov.setSub('النتيجة');
        const pct = Math.round(score / qs.length * 100);
        body.append(h('div', { class: 'st-empty' }, h('div', { style: { fontSize: '40px', fontWeight: 700, color: pct >= 70 ? '#3FBF7F' : pct >= 50 ? '#F08A4B' : '#E5484D' } }, `${score} / ${qs.length}`),
          h('div', { style: { color: 'var(--muted)' } }, pct >= 80 ? 'ممتاز، كمّل كذا' : pct >= 60 ? 'زين، راجع اللي غلطت فيها' : 'تحتاج تراجع المحاضرة مرة ثانية'),
          h('div', { class: 'st-acts', style: { justifyContent: 'center' } }, h('button', { class: 'btn primary', type: 'button', onclick: start }, 'اختبار جديد'))));
        if (wrong.length) { const l = h('div', { class: 'st-list' }); for (const q of wrong) l.append(h('div', { class: 'st-card' }, h('div', { class: 'q ltr', dir: 'auto' }, q.q), h('div', { class: 'a ltr', dir: 'auto' }, '✓ ' + q.options[q.correct]), h('div', { class: 'a ltr', dir: 'auto', style: { color: 'var(--muted)' } }, q.explanation), h('div', { class: 'm' }, h('button', { class: 'linkbtn', type: 'button', onclick: () => { ov.done(); ctx.openLecture(q.lid, q.page - 1); } }, 'سلايد ' + q.page)))); body.append(h('div', { style: { fontWeight: 700, margin: '8px 0' } }, 'الأسئلة اللي غلطت فيها'), l); }
        return;
      }
      const q = qs[i]; ov.setSub(`سؤال ${i + 1} من ${qs.length} · الصح ${score}`);
      body.append(h('div', { class: 'st-prog' }, h('div', { style: { width: (i / qs.length * 100) + '%' } })), h('div', { class: 'st-q ltr', dir: 'auto' }, q.q));
      const opts = h('div', { class: 'st-opts' });
      q.options.forEach((o, k) => {
        const cls = picked == null ? '' : k === q.correct ? ' right' : k === picked ? ' wrongp' : ' dim';
        opts.append(h('button', { type: 'button', class: 'st-opt ltr' + cls, dir: 'auto', disabled: picked != null, onclick: () => choose(k) }, h('b', {}, 'ABCD'[k] || k + 1), h('span', {}, o)));
      });
      body.append(opts);
      if (picked != null) body.append(h('div', { class: 'st-exp ltr', dir: 'auto' }, q.explanation), h('div', { class: 'st-acts' }, h('button', { class: 'btn primary', type: 'button', onclick: next }, i + 1 < qs.length ? 'السؤال الجاي (Enter)' : 'النتيجة'), h('button', { class: 'linkbtn', type: 'button', onclick: () => { ov.done(); ctx.openLecture(q.lid, q.page - 1); } }, 'روح لسلايد ' + q.page)));
    };
    const choose = k => { if (picked != null) return; picked = k; if (k === qs[i].correct) score++; else wrong.push(qs[i]); draw(); };
    const next = () => { i++; picked = null; draw(); };
    ov.bg._key = e => { if (i >= qs.length) return; if (picked == null && ['1', '2', '3', '4', 'a', 'b', 'c', 'd'].includes(e.key.toLowerCase())) { e.preventDefault(); choose('1234'.includes(e.key) ? Number(e.key) - 1 : 'abcd'.indexOf(e.key.toLowerCase())); } else if (picked != null && e.key === 'Enter') { e.preventDefault(); next(); } };
    draw();
  }
  start();
}

export async function testKey(k) {
  const r = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?pageSize=5&key=${encodeURIComponent(k)}`);
  const j = await r.json().catch(() => ({}));
  if (j.error) throw new Error(j.error.message);
  modelsP = null; goodModel = null;
  return true;
}
